function renderDepartments(){const admin=adminMode(),departments=orgDepartments();document.querySelector('#content').innerHTML=`<section class="product-head"><div><p class="eyebrow">DEPARTAMENTOS</p><h1>La estructura de ${esc(company.name)}.</h1><p>Responsabilidades, alcance, puestos y responsables en un catálogo controlado.</p></div>${admin?'<button class="button primary" id="new-department">Nuevo departamento</button>':''}</section><section class="department-grid">${departments.map(item=>{const positions=orgPositions(item.name);return `<article style="--department:${esc(item.color||'#1769e8')}"><button class="department-open" data-department="${Number(item.id)}" aria-label="Abrir ${esc(item.name)}"><div class="department-title"><i></i><span>${positions.length} ${positions.length===1?'puesto':'puestos'}</span></div><h2>${esc(item.name)}</h2><p>${esc(item.purpose||'Propósito pendiente de documentar.')}</p><footer><b>${Number(item.member_count)||0} integrantes</b><span>${item.manager_name?`Responsable: ${esc(item.manager_name)}`:'Responsable por asignar'} →</span></footer></button></article>`}).join('')||'<section class="card empty">Aún no hay departamentos activos.</section>'}</section>`;document.querySelector('#new-department')?.addEventListener('click',()=>showDepartmentEditor());bind('[data-department]','click',e=>showDepartmentDetail(Number(e.currentTarget.dataset.department)))}
function showDepartmentDetail(departmentId){const department=orgDepartments().find(item=>Number(item.id)===departmentId);if(!department)return;const admin=adminMode(),positions=orgPositions(department.name);const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<section class="card modal-card department-sheet"><div class="modal-title"><div><p class="eyebrow">DEPARTAMENTO</p><h2>${esc(department.name)}</h2><p>${esc(department.purpose||'Propósito pendiente.')}</p></div><button class="button small secondary" data-close-modal>Cerrar</button></div><div class="department-facts"><article><small>RESPONSABILIDADES</small><p>${esc(department.responsibilities||'Pendientes de documentar.')}</p></article><article><small>ALCANCE</small><p>${esc(department.scope_text||'Pendiente de documentar.')}</p></article><article><small>RESPONSABLE</small><p>${esc(department.manager_name||'Por asignar')}</p></article></div><div class="position-head"><div><p class="eyebrow">PUESTOS</p><h3>${positions.length} configurados</h3></div>${admin?'<button class="button small primary" id="new-position">Agregar puesto</button>':''}</div><div class="position-list">${positions.map(position=>`<button data-position="${Number(position.id)}"><span><b>${esc(position.name)}</b><small>${esc(position.purpose||'Propósito pendiente.')}</small></span><i>${Number(position.member_count)||0} personas ${admin?'· Editar':''}</i></button>`).join('')||'<p class="muted">Aún no hay puestos configurados.</p>'}</div><div class="modal-actions">${department.name==='Distribución'?'<button class="button secondary" data-open-map>Ver mapa de actividades</button>':''}${admin?'<button class="button primary" id="edit-department">Editar departamento</button>':''}</div></section>`;document.body.append(modal);bindModalClose(modal);attachResponsibilities(modal.querySelector('.modal-card'),{departmentId});modal.querySelector('#edit-department')?.addEventListener('click',()=>{modal.remove();showDepartmentEditor(department)});modal.querySelector('#new-position')?.addEventListener('click',()=>{modal.remove();showPositionEditor(department)});modal.querySelectorAll('[data-position]').forEach(button=>button.onclick=()=>{const position=positions.find(item=>Number(item.id)===Number(button.dataset.position));if(position){modal.remove();if(admin)showPositionEditor(department,position);else showPositionDetail(position)}});modal.querySelector('[data-open-map]')?.addEventListener('click',()=>{modal.remove();navigate('map')})}
function showDepartmentEditor(department=null){if(data.user.role!=='admin')return;const managers=[data.user,...(data.team||[])].filter(person=>Number(person.is_active??1)===1&&['c_level','manager'].includes(person.access_level));const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<section class="card modal-card"><div class="modal-title"><div><p class="eyebrow">CATÁLOGO ORGANIZACIONAL</p><h2>${department?'Editar departamento':'Nuevo departamento'}</h2></div><button class="button small secondary" data-close-modal>Cerrar</button></div><form id="department-form"><div class="grid two"><label class="field"><span>Nombre</span><input name="name" value="${esc(department?.name||'')}" maxlength="120" required></label><label class="field"><span>Responsable</span><select name="managerUserId"><option value="">Por asignar</option>${managers.map(person=>`<option value="${Number(person.id)}" ${Number(department?.manager_user_id)===Number(person.id)?'selected':''}>${esc(person.name)}</option>`).join('')}</select></label><label class="field wide"><span>Propósito</span><textarea name="purpose" minlength="5" required>${esc(department?.purpose||'')}</textarea></label><label class="field"><span>Responsabilidades</span><textarea name="responsibilities">${esc(department?.responsibilities||'')}</textarea></label><label class="field"><span>Alcance</span><textarea name="scope">${esc(department?.scope_text||'')}</textarea></label><label class="field"><span>Color del mapa</span><input name="color" type="color" value="${esc(department?.color||'#1769e8')}"></label></div><div class="modal-actions split">${department?'<button class="button danger" type="button" id="archive-department">Archivar</button>':'<span></span>'}<span></span><button class="button secondary" type="button" data-close-modal>Cancelar</button><button class="button primary" type="submit">Guardar departamento</button></div></form></section>`;document.body.append(modal);bindModalClose(modal);modal.querySelector('#department-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{await api('save-department',{method:'POST',body:{...values,departmentId:department?.id||0}});modal.remove();await reload();navigate('departments');toast('Departamento guardado.')}catch(err){toast(err.message,true);button.disabled=false}};modal.querySelector('#archive-department')?.addEventListener('click',async e=>{if(!confirm('¿Archivar este departamento? Sólo es posible si no tiene personas asignadas.'))return;e.currentTarget.disabled=true;try{await api('archive-department',{method:'POST',body:{departmentId:department.id}});modal.remove();await reload();navigate('departments');toast('Departamento archivado.')}catch(err){toast(err.message,true);e.currentTarget.disabled=false}})}
async function showPositionEditor(department,position=null){if(data.user.role!=='admin')return;const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<section class="card modal-card"><div class="modal-title"><div><p class="eyebrow">${esc(department.name)} · PUESTO</p><h2>${position?'Editar puesto':'Nuevo puesto'}</h2></div><button class="button small secondary" data-close-modal>Cerrar</button></div><form id="position-form"><label class="field"><span>Nombre del puesto</span><input name="name" value="${esc(position?.name||'')}" maxlength="120" required></label><label class="field"><span>Propósito</span><textarea name="purpose" minlength="5" required>${esc(position?.purpose||'')}</textarea></label><div id="position-tags-editor"></div><details class="position-legacy"><summary>Notas anteriores del puesto</summary><p class="muted">Se conservan como referencia; selecciona arriba las etiquetas que correspondan.</p><label class="field"><span>Responsabilidades anteriores</span><textarea name="responsibilities">${esc(position?.responsibilities||'')}</textarea></label><label class="field"><span>Alcance anterior</span><textarea name="scope">${esc(position?.scope_text||'')}</textarea></label><label class="field"><span>Capacidades anteriores</span><textarea name="capabilities">${esc(position?.capabilities||'')}</textarea></label></details><div class="modal-actions split">${position?'<button class="button danger" type="button" id="archive-position">Archivar</button>':'<span></span>'}<span></span><button class="button secondary" type="button" data-close-modal>Cancelar</button><button class="button primary" type="submit">Guardar puesto</button></div></form></section>`;document.body.append(modal);bindModalClose(modal);const saveButton=modal.querySelector('#position-form .button.primary');saveButton.disabled=true;let tagEditor;modal.querySelector('#position-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector('[type="submit"]');button.disabled=true;try{await api('save-position',{method:'POST',body:{...values,tags:tagEditor.data(),departmentId:department.id,positionId:position?.id||0}});modal.remove();await reload();navigate('departments');toast('Puesto guardado.')}catch(err){toast(err.message,true);button.disabled=false}};modal.querySelector('#archive-position')?.addEventListener('click',async e=>{if(!confirm('¿Archivar este puesto? Sólo es posible si no tiene personas asignadas.'))return;e.currentTarget.disabled=true;try{await api('archive-position',{method:'POST',body:{positionId:position.id}});modal.remove();await reload();navigate('departments');toast('Puesto archivado.')}catch(err){toast(err.message,true);e.currentTarget.disabled=false}});if(position)attachResponsibilities(modal.querySelector('#position-form'),{positionId:position.id});tagEditor=await window.PositionTags.mount(modal.querySelector('#position-tags-editor'),department.id,position?.tags||{});saveButton.disabled=false;}
